description:
Write your own versions of four C string functions. Strings are `char` arrays ending in `'\0'`. Use pointers that walk the strings, **no square brackets** and no library string functions.

```cpp
std::size_t myStrlen(const char* s);
char* myStrcpy(char* destination, const char* source);
int myStrcmp(const char* a, const char* b);
const char* myStrstr(const char* haystack, const char* needle);
```

- **myStrlen** counts the characters before the zero.
- **myStrcpy** copies `source`, including its zero, into `destination` and returns `destination`.
- **myStrcmp** compares character by character as `unsigned char` values. It returns a negative number if `a` comes first, a positive number if `b` comes first, and 0 if they are equal. A string that is a prefix of the other comes first.
- **myStrstr** returns a pointer to the first place `needle` appears inside `haystack`, or `nullptr`. An empty needle is found at the very start.

starter.solution.cpp:
#include <cstddef>

std::size_t myStrlen(const char* s) { return 0; }
char* myStrcpy(char* destination, const char* source) { return nullptr; }
int myStrcmp(const char* a, const char* b) { return 0; }
const char* myStrstr(const char* haystack, const char* needle) { return nullptr; }

solution.solution.cpp:
#include <cstddef>

std::size_t myStrlen(const char* s)
{
    const char* p{ s };
    while (*p != '\0') ++p;
    return static_cast<std::size_t>(p - s);
}

char* myStrcpy(char* destination, const char* source)
{
    char* out{ destination };
    while ((*out++ = *source++) != '\0') {}
    return destination;
}

int myStrcmp(const char* a, const char* b)
{
    while (*a != '\0' && *a == *b) { ++a; ++b; }
    return static_cast<unsigned char>(*a) - static_cast<unsigned char>(*b);
}

const char* myStrstr(const char* haystack, const char* needle)
{
    if (*needle == '\0') return haystack;
    for (const char* start{ haystack }; *start != '\0'; ++start)
    {
        const char* h{ start };
        const char* n{ needle };
        while (*n != '\0' && *h == *n) { ++h; ++n; }
        if (*n == '\0') return start;
    }
    return nullptr;
}

unitTests:
TEST("length") {
    CHECK_EQ(myStrlen("pointer"), 7u);
    CHECK_EQ(myStrlen(""), 0u);
    const char text[]{ "abc\0def" };
    CHECK_EQ(myStrlen(text), 3u);
}
TEST("copy") {
    char buffer[16];
    for (char& c : buffer) c = 'x';
    CHECK(myStrcpy(buffer, "hello") == buffer);
    CHECK_EQ(std::string(buffer), std::string("hello"));
    CHECK_EQ(buffer[5], '\0');
    CHECK_EQ(buffer[6], 'x');
    myStrcpy(buffer, "");
    CHECK_EQ(buffer[0], '\0');
}
TEST("compare") {
    CHECK_EQ(myStrcmp("apple", "apple"), 0);
    CHECK(myStrcmp("apple", "apricot") < 0);
    CHECK(myStrcmp("pear", "peach") > 0);
    CHECK(myStrcmp("app", "apple") < 0);
    CHECK(myStrcmp("apple", "app") > 0);
    CHECK(myStrcmp("", "") == 0);
    CHECK(myStrcmp("\xC3\xA9", "z") > 0);
}
TEST("search") {
    const char* text{ "a pointer points" };
    CHECK(myStrstr(text, "point") == text + 2);
    CHECK(myStrstr(text, "points") == text + 10);
    CHECK(myStrstr(text, "pointless") == nullptr);
    CHECK(myStrstr(text, "") == text);
    CHECK(myStrstr("aab", "ab") != nullptr);
    CHECK(myStrstr("", "a") == nullptr);
}

